{"compatibility":"minor","safety_note_md":"# SafeStan Safety Note

Compatibility: minor.

Protected data: `x1`, `y1`, and `x2`.

Generated files: `model_safe.stan`, `data_safe.json`.

Changes: added the explicit prior `phi ~ uniform(0, 2 * pi())` for `phi`, matching the original finite constraint `real<lower=0, upper=2 * pi()> phi` and the model comment indicating an implicit uniform prior. No data fields were changed. The protected observations remain top-level data variables and are each scored exactly once by built-in distributions.
","model_safe_stan":"data {
  int<lower=1> N1; // Number of complete observations
  vector[N1] x1;   // Complete observations
  vector[N1] y1;   // Complete observations
  real<lower=0> alpha1; // Complete observation covariate distribution shape
  real<lower=0> beta1;  // Complete observation covariate distribution rate

  int<lower=1> N2;      // Number of incomplete observations
  vector[N2] x2;        // Incomplete observations
  real<lower=0> alpha2; // Incomplete observation covariate distribution shape
  real<lower=0> beta2;  // Incomplete observation covariate distribution rate

  int<lower=1> N_grid; // Number of grid points for quantifying functional behavior
  vector[N_grid] x_grid; // Grid points for quantifying functional behavior
}

parameters {
  real<lower=0> A;                   // Variate units
  real<lower=0, upper=2 * pi()> phi; // Radians
  real<lower=0> omega1;              // Radians per second
  real<lower=0> omega2;              // Radians per second
  real<lower=0> gamma;               // Seconds
  real<lower=0> sigma;               // Variate units
}

model {
  A ~ normal(0, 5);
  phi ~ uniform(0, 2 * pi());
  omega1 ~ normal(0, 5);
  omega2 ~ normal(0, 5);
  gamma ~ normal(0, 1);
  sigma ~ normal(0, 0.25);

  x1 ~ gamma(alpha1, beta1 + gamma * omega1);
  y1 ~ normal(A * sin(omega1 * x1 + phi), sigma);

  x2 ~ gamma(alpha2, beta2 + gamma * omega2);
}

generated quantities {
  array[N1] real x1_pred; // Complete observation covariate retrodiction
  array[N1] real y1_pred; // Complete observation conditional variate retrodiction
  array[N2] real x2_pred; // Incomplete observation covariate retrodiction
  array[N2] real y2_pred; // Incomplete observation conditional variate prediction

  array[N_grid] real f1_grid;      // Inferred functional behavior along covariate grid
  array[N_grid] real f2_grid;      // Inferred functional behavior along covariate grid
  array[N_grid] real y2_pred_grid; // Predictive variate behavior along covariate grid

  for (n in 1:N1) {
    x1_pred[n] = gamma_rng(alpha1, beta1 + gamma * omega1);
    y1_pred[n] = normal_rng(A * sin(omega1 * x1[n] + phi), sigma);
  }

  for (n in 1:N2) {
    x2_pred[n] = gamma_rng(alpha2, beta2 + gamma * omega2);
    y2_pred[n] = normal_rng(A * sin(omega2 * x2[n] + phi), sigma);
  }

  for (n in 1:N_grid) {
    f1_grid[n] = A * sin(omega1 * x_grid[n] + phi);
    f2_grid[n] = A * sin(omega2 * x_grid[n] + phi);
    y2_pred_grid[n] = normal_rng(f2_grid[n], sigma);
  }
}
","data_safe_json":"{"N1":3,"N2":1,"N_grid":3,"alpha1":2.465006750021767,"alpha2":3.8215397685253967,"beta1":1.3779189159132301,"beta2":1.645823044047622,"x1":[5.761808476683793,3.683401612574655,5.41300117075016],"x2":[5.103861141777648],"x_grid":[1.0,2.0,3.0],"y1":[3.0,2.0,3.0]}","protected_variables":["x1","y1","x2"]}
